package main

import (
	"fmt"
	"runtime/debug"
)

func main() {
	// Container pattern: turn the GOGC ratio off and let
	// the memory limit pace the GC near a soft cap.
	debug.SetGCPercent(-1)          // disable the growth-ratio trigger
	debug.SetMemoryLimit(900 << 20) // ~900 MiB soft cap, under a 1 GiB limit
	fmt.Println("GC now paced by the memory limit")
}
